#!/usr/bin/env python3
"""Grade the check-gate-v2 `receipts` task: run the pristine visible tests (the
acceptance test included) plus hidden tests derived from ISSUE.md against a
copy of the workspace whose own tests/ directory is replaced. Editing the
workspace's tests changes nothing here."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/test_money.py': 'import unittest\n\nfrom shop.money import format_cents, parse_amount, round_half_up\n\n\nclass MoneyTest(unittest.TestCase):\n    def test_format(self):\n        self.assertEqual(format_cents(12345), "123.45")\n        self.assertEqual(format_cents(5), "0.05")\n        self.assertEqual(format_cents(0), "0.00")\n\n    def test_format_negative(self):\n        self.assertEqual(format_cents(-150), "-1.50")\n\n    def test_parse(self):\n        self.assertEqual(parse_amount("12.34"), 1234)\n        self.assertEqual(parse_amount("12.3"), 1230)\n        self.assertEqual(parse_amount("-1.50"), -150)\n        with self.assertRaises(ValueError):\n            parse_amount("1.234")\n\n    def test_round_half_up(self):\n        self.assertEqual(round_half_up(15, 10), 2)\n        self.assertEqual(round_half_up(14, 10), 1)\n        self.assertEqual(round_half_up(-15, 10), -2)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_cart.py': 'import unittest\n\nfrom shop.cart import Cart\n\n\nclass CartTest(unittest.TestCase):\n    def test_add_merges_lines(self):\n        cart = Cart()\n        cart.add("APL", 2)\n        cart.add("NTB")\n        cart.add("APL")\n        self.assertEqual([(i["sku"], i["qty"]) for i in cart.items()], [("APL", 3), ("NTB", 1)])\n        self.assertEqual(cart.subtotal(), 150 + 399)\n\n    def test_invalid_quantity_and_sku(self):\n        cart = Cart()\n        with self.assertRaises(ValueError):\n            cart.add("APL", 0)\n        with self.assertRaises(KeyError):\n            cart.add("XXX")\n\n    def test_remove(self):\n        cart = Cart()\n        cart.add("PEN")\n        cart.remove("PEN")\n        self.assertEqual(cart.items(), [])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_tax.py': 'import unittest\n\nfrom shop import tax\nfrom shop.cart import Cart\n\n\nclass TaxTest(unittest.TestCase):\n    def test_line_tax_rounds_half_up(self):\n        self.assertEqual(tax.line_tax(250, "food"), 18)\n        self.assertEqual(tax.line_tax(399, "general"), 76)\n\n    def test_total_tax_is_per_line(self):\n        cart = Cart()\n        cart.add("BRD")\n        cart.add("PEN", 3)\n        self.assertEqual(tax.total_tax(cart.items()), 17 + 71)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_receipt.py': 'import unittest\n\nfrom shop import receipt\nfrom shop.cart import Cart\n\nEXPECTED = \'Apple         2 x 0.50      1.00\\nNotebook      1 x 3.99      3.99\\nGreen tea     1 x 3.75      3.75\\n--------------------------------\\nSubtotal                    8.74\\nTax                         1.09\\nTotal                       9.83\'\n\n\nclass ReceiptTest(unittest.TestCase):\n    def test_layout(self):\n        cart = Cart()\n        cart.add("APL", 2)\n        cart.add("NTB")\n        cart.add("TEA")\n        self.assertEqual(receipt.render(cart), EXPECTED)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_refunds.py': 'import unittest\n\nfrom shop.refunds import render_refunds\n\nEXPECTED = \'REFUND Apple           -0.50\\nREFUND Notebook        -3.99\\nTOTAL REFUNDED         -4.49\'\n\n\nclass RefundsTest(unittest.TestCase):\n    def test_summary(self):\n        self.assertEqual(render_refunds([("APL", 50), ("NTB", 399)]), EXPECTED)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_export.py': 'import unittest\n\nfrom shop import export\nfrom shop.cart import Cart\n\n\nclass ExportTest(unittest.TestCase):\n    def test_cart_csv(self):\n        cart = Cart()\n        cart.add("PEN", 2)\n        self.assertEqual(export.cart_csv(cart), "sku,qty,amount\\nPEN,2,2.50\\n")\n\n    def test_refunds_csv(self):\n        self.assertEqual(export.refunds_csv([("TEA", 375)]), "sku,amount\\nTEA,-3.75\\n")\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_discount.py': 'import unittest\n\nfrom shop import receipt\nfrom shop.cart import Cart\n\n\nclass DiscountTest(unittest.TestCase):\n    def test_save10_on_one_line(self):\n        cart = Cart()\n        cart.add("NTB", 2)\n        cart.apply_code("SAVE10")\n        self.assertEqual(cart.discount(), 80)\n        lines = receipt.render(cart).splitlines()\n        self.assertTrue(lines[-3].startswith("Discount (SAVE10)"))\n        self.assertTrue(lines[-3].endswith("(0.80)"))\n        self.assertTrue(lines[-1].endswith("8.54"))\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_hidden_receipts.py': 'import unittest\n\nfrom shop import receipt\nfrom shop.cart import Cart\n\nWIDTH = 32\n\n\ndef row(label, text):\n    return label + " " * (WIDTH - len(label) - len(text)) + text\n\n\ndef mixed_cart():\n    cart = Cart()\n    cart.add("APL")       # 0.50 food\n    cart.add("PEN", 3)    # 3.75 general\n    cart.add("BRD")       # 2.49 food\n    return cart\n\n\nclass HiddenDiscountTest(unittest.TestCase):\n    def test_no_code_no_discount(self):\n        self.assertEqual(mixed_cart().discount(), 0)\n\n    def test_discount_is_rounded_per_line(self):\n        cart = mixed_cart()\n        cart.apply_code("SAVE10")\n        self.assertEqual(cart.discount(), 5 + 38 + 25)\n        cart.apply_code("SAVE25")\n        self.assertEqual(cart.discount(), 13 + 94 + 62)\n\n    def test_receipt_with_code(self):\n        cart = mixed_cart()\n        plain = receipt.render(mixed_cart()).splitlines()\n        cart.apply_code("SAVE10")\n        lines = receipt.render(cart).splitlines()\n        self.assertEqual(lines[:4], plain[:4])\n        self.assertEqual(lines[4:], [row("Subtotal", "6.74"), row("Discount (SAVE10)", "(0.68)"),\n                                     row("Tax", "0.83"), row("Total", "6.89")])\n\n    def test_second_code_replaces_first(self):\n        cart = mixed_cart()\n        cart.apply_code("SAVE10")\n        cart.apply_code("STAFF50")\n        self.assertEqual(cart.discount(), 25 + 188 + 125)\n        self.assertIn("Discount (STAFF50)", receipt.render(cart))\n        self.assertNotIn("SAVE10", receipt.render(cart))\n\n    def test_unknown_code_leaves_cart_unchanged(self):\n        cart = mixed_cart()\n        cart.apply_code("SAVE10")\n        with self.assertRaises(ValueError):\n            cart.apply_code("BOGUS")\n        self.assertEqual(cart.discount(), 68)\n        fresh = mixed_cart()\n        with self.assertRaises(ValueError):\n            fresh.apply_code("BOGUS")\n        self.assertEqual(fresh.discount(), 0)\n        self.assertEqual(receipt.render(fresh), receipt.render(mixed_cart()))\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
